<?php
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../includes/auth.php';
requireRole('admin');
$admin=currentUser();
$pickupId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:filter_input(INPUT_POST,'pickup_id',FILTER_VALIDATE_INT)?:0;
if($_SERVER['REQUEST_METHOD']==='POST'){
 require_csrf();$collectorId=filter_var($_POST['collector_id']??0,FILTER_VALIDATE_INT)?:0;$connection=db();
 try{$connection->begin_transaction();$lock=$connection->prepare('SELECT status,user_id,reference_number FROM pickup_requests WHERE id=? FOR UPDATE');$lock->bind_param('i',$pickupId);$lock->execute();$locked=$lock->get_result()->fetch_assoc();$lock->close();if(!$locked||!in_array($locked['status'],['Approved','Scheduled','Collector Assigned'],true))throw new RuntimeException('Accept or schedule the pickup before assigning a collector.');$cs=$connection->prepare('SELECT id,full_name FROM collectors WHERE id=? AND status="active" FOR UPDATE');$cs->bind_param('i',$collectorId);$cs->execute();$collector=$cs->get_result()->fetch_assoc();$cs->close();if(!$collector)throw new RuntimeException('Choose an active collector.');$old=$connection->prepare('SELECT id FROM pickup_assignments WHERE pickup_request_id=? ORDER BY assigned_at DESC,id DESC LIMIT 1 FOR UPDATE');$old->bind_param('i',$pickupId);$old->execute();$assignment=$old->get_result()->fetch_assoc();$old->close();$adminId=(int)$admin['id'];$assignedStatus='Assigned';if($assignment){$update=$connection->prepare('UPDATE pickup_assignments SET collector_id=?,assigned_by=?,status=? WHERE id=?');$update->bind_param('iisi',$collectorId,$adminId,$assignedStatus,$assignment['id']);$update->execute();$update->close();}else{$insert=$connection->prepare('INSERT INTO pickup_assignments (pickup_request_id,collector_id,assigned_by,status) VALUES (?,?,?,?)');$insert->bind_param('iiis',$pickupId,$collectorId,$adminId,$assignedStatus);$insert->execute();$insert->close();}$previous=$locked['status'];$next='Collector Assigned';$update=$connection->prepare('UPDATE pickup_requests SET status=? WHERE id=?');$update->bind_param('si',$next,$pickupId);$update->execute();$update->close();if($previous!==$next)createPickupStatusEntry($pickupId,$previous,$next,$adminId,'Collector assigned: '.$collector['full_name']);else createPickupStatusEntry($pickupId,$previous,$next,$adminId,'Collector assignment updated: '.$collector['full_name']);createNotification((int)$locked['user_id'],'Collector assigned','A collector has been assigned to pickup '.$locked['reference_number'].'.','info',$pickupId);logAdminAction($adminId,'Collector assigned to pickup','Pickup '.$locked['reference_number'].' assigned to '.$collector['full_name'].' (#'.$collectorId.').');$connection->commit();setFlash('success','Collector assigned to the pickup.');}catch(RuntimeException $e){$connection->rollback();setFlash('error',$e->getMessage());}catch(Throwable $e){$connection->rollback();error_log('EcoLoop collector assignment failed: '.$e->getMessage());setFlash('error','The collector could not be assigned. Please try again.');}
 redirect('admin/pickup-details.php?id='.$pickupId);
}
$stmt=db()->prepare('SELECT p.*,u.email,u.full_name AS profile_name FROM pickup_requests p JOIN users u ON u.id=p.user_id WHERE p.id=?');$stmt->bind_param('i',$pickupId);$stmt->execute();$pickup=$stmt->get_result()->fetch_assoc();$stmt->close();
if(!$pickup){setFlash('error','Pickup request not found.');redirect('admin/pickups.php');}
$stmt=db()->prepare('SELECT item_category,quantity,notes FROM pickup_items WHERE pickup_request_id=? ORDER BY id');$stmt->bind_param('i',$pickupId);$stmt->execute();$items=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();
$stmt=db()->prepare('SELECT h.previous_status,h.new_status,h.note,h.created_at,u.full_name actor FROM pickup_status_history h LEFT JOIN users u ON u.id=h.changed_by WHERE h.pickup_request_id=? ORDER BY h.created_at DESC,h.id DESC');$stmt->bind_param('i',$pickupId);$stmt->execute();$history=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();
$stmt=db()->prepare('SELECT v.id,v.total_points,v.phone_value_total,v.created_at,u.full_name verifier FROM pickup_verifications v JOIN users u ON u.id=v.verified_by WHERE v.pickup_request_id=?');$stmt->bind_param('i',$pickupId);$stmt->execute();$verification=$stmt->get_result()->fetch_assoc();$stmt->close();$verifiedItems=[];
if($verification){$stmt=db()->prepare('SELECT item_category,quantity,points_per_piece,subtotal_points,monetary_value_per_piece,condition_notes FROM pickup_verified_items WHERE verification_id=? ORDER BY id');$stmt->bind_param('i',$verification['id']);$stmt->execute();$verifiedItems=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();}
$assignmentStmt=db()->prepare('SELECT a.status,c.full_name,c.mobile_number,c.email FROM pickup_assignments a JOIN collectors c ON c.id=a.collector_id WHERE a.pickup_request_id=? ORDER BY a.assigned_at DESC,a.id DESC LIMIT 1');$assignmentStmt->bind_param('i',$pickupId);$assignmentStmt->execute();$assignment=$assignmentStmt->get_result()->fetch_assoc();$assignmentStmt->close();
$activeCollectors=db()->query('SELECT id,full_name FROM collectors WHERE status="active" AND user_id IS NOT NULL ORDER BY full_name')->fetch_all(MYSQLI_ASSOC);
$pageTitle='Pickup Details | Eco-Loop';require __DIR__.'/../includes/header.php';
?>
<div class="dashboard-shell"><?php require __DIR__.'/../includes/navigation.php';?><main class="main-content">
<div class="page-header"><div><span class="eyebrow">Pickup operations</span><h1><?php echo e($pickup['reference_number']);?></h1><p>Status: <?php echo e($pickup['status']==='Approved'?'Accepted':$pickup['status']);?></p></div><a class="btn btn-outline" href="<?php echo e(APP_ROOT.'/admin/pickups.php');?>">Back to requests</a></div>
<div class="info-grid"><section class="content-card"><h2>Customer and pickup</h2><p><strong>Customer:</strong> <?php echo e($pickup['customer_name']?:$pickup['profile_name']);?> · #<?php echo(int)$pickup['user_id'];?></p><p><strong>Contact:</strong> <a href="tel:<?php echo e($pickup['contact_number']?:'');?>"><?php echo e($pickup['contact_number']?:'Not provided');?></a> · <a href="mailto:<?php echo e($pickup['email']);?>">Email customer</a></p><p><strong>Address:</strong> <?php echo e($pickup['pickup_address']);?></p><p><strong>Service:</strong> <?php echo e($pickup['service_type']==='priority'?'Priority Collection':'Convenience (Saver)');?> · <?php echo e(formatCurrency((float)$pickup['service_fee']));?></p><p><strong>Distance:</strong> <?php echo $pickup['distance_km']!==null?e($pickup['distance_km'].' km straight-line estimate'):'Not available';?> · <?php echo e($pickup['distance_method']?:'');?></p><p><strong>Preferred:</strong> <?php echo e($pickup['preferred_date']?:'As soon as available');?> <?php echo e($pickup['preferred_time']?substr($pickup['preferred_time'],0,5):'');?></p><p><strong>Submitted:</strong> <?php echo e(date('M j, Y g:i A',strtotime($pickup['created_at'])));?></p><p><strong>Notes:</strong> <?php echo e($pickup['description']?:'None');?></p><p><strong>Map coordinates:</strong> <?php echo $pickup['latitude']!==null?e($pickup['latitude'].', '.$pickup['longitude']):'No pin saved';?></p><?php if($pickup['latitude']!==null):?><p><a target="_blank" rel="noopener" href="https://www.google.com/maps?q=<?php echo rawurlencode($pickup['latitude'].','.$pickup['longitude']);?>">Open in Google Maps</a></p><div id="admin-pickup-location-map" class="dashboard-map"></div><?php endif;?></section>
<section class="content-card"><h2>Customer-declared e-waste</h2><?php if($items):?><ul><?php foreach($items as $item):?><li><?php echo e($item['item_category']);?> × <?php echo(int)$item['quantity'];?><?php if($item['notes']):?> · <?php echo e($item['notes']);?><?php endif;?></li><?php endforeach;?></ul><?php else:?><p>No item categories recorded.</p><?php endif;?>
<h2>Verified collection items</h2><?php if($verification):?><p><strong><?php echo(int)$verification['total_points'];?> points eligible</strong> · phone valuation ₱<?php echo e(number_format((float)$verification['phone_value_total'],2));?> separately · verified by <?php echo e($verification['verifier']);?> on <?php echo e(date('M j, Y',strtotime($verification['created_at'])));?></p><ul><?php foreach($verifiedItems as $item):?><li><?php echo e($item['item_category']);?> × <?php echo(int)$item['quantity'];?> · <?php echo(int)$item['points_per_piece'];?> points each = <?php echo(int)$item['subtotal_points'];?> points<?php if($item['item_category']==='Phone'):?> · ₱<?php echo e(number_format((float)$item['monetary_value_per_piece'],2));?> each<?php endif;?><?php if($item['condition_notes']):?> · <?php echo e($item['condition_notes']);?><?php endif;?></li><?php endforeach;?></ul><?php else:?><p>Items have not been verified.</p><?php endif;?></section></div>
<section class="content-card"><h2>Collector assignment</h2><?php if($assignment):?><p><strong><?php echo e($assignment['full_name']);?></strong> · <?php echo e($assignment['mobile_number']);?> · <?php echo e($assignment['email']);?> · <?php echo e($assignment['status']);?></p><?php else:?><p>No collector assigned yet.</p><?php endif;?><?php if(in_array($pickup['status'],['Approved','Scheduled','Collector Assigned'],true)&&$activeCollectors):?><form method="post" class="inline-form"><?php echo csrf_field();?><input type="hidden" name="pickup_id" value="<?php echo(int)$pickupId;?>"><label for="collector_id">Assign or reassign collector</label><select name="collector_id" id="collector_id" required><option value="">Choose collector</option><?php foreach($activeCollectors as $collector):?><option value="<?php echo(int)$collector['id'];?>" <?php echo $assignment&&$assignment['full_name']===$collector['full_name']?'selected':'';?>><?php echo e($collector['full_name']);?></option><?php endforeach;?></select><button class="btn btn-primary">Save assignment</button></form><?php elseif(!$activeCollectors):?><p>No active collectors are configured yet. Add an account in Collector Management.</p><?php endif;?></section>
<section class="content-card"><h2>Request history</h2><?php if($history):?><ul class="timeline-list"><?php foreach($history as $entry):?><li><span><strong><?php echo e($entry['new_status']);?></strong><?php if($entry['previous_status']):?> · from <?php echo e($entry['previous_status']);?><?php endif;?><?php if($entry['note']):?><br><?php echo e($entry['note']);?><?php endif;?></span><small><?php echo e($entry['actor']?:'System');?> · <?php echo e(date('M j, Y g:i A',strtotime($entry['created_at'])));?></small></li><?php endforeach;?></ul><?php else:?><p>No status history saved.</p><?php endif;?></section>
</main></div><?php if($pickup['latitude']!==null):?><script>document.addEventListener('DOMContentLoaded',function(){if(typeof initializePickupMap==='function')initializePickupMap({mapId:'admin-pickup-location-map',defaultLat:Number(<?php echo json_encode((float)$pickup['latitude']);?>),defaultLng:Number(<?php echo json_encode((float)$pickup['longitude']);?>),latInput:{value:''},lngInput:{value:''},markers:[{lat:Number(<?php echo json_encode((float)$pickup['latitude']);?>),lng:Number(<?php echo json_encode((float)$pickup['longitude']);?>),reference_number:<?php echo json_encode($pickup['reference_number'],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP);?>,address:<?php echo json_encode($pickup['pickup_address'],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP);?>,status:'Customer pickup'}],editable:false,allowUnselected:true});});</script><?php endif;?><?php require __DIR__.'/../includes/footer.php';?>
